const fs = require('fs'), path = require('path'), vm = require('vm');
const dir = '分析产出/持仓面板';
const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
const wasmB64 = html.match(/id="sqlWasmB64">([\s\S]*?)<\/script>/)[1];

const els = {};
function el(id) {
  if (!els[id]) els[id] = { innerHTML: '', textContent: '', value: '', style: {}, dataset: {},
    classList: { toggle(){}, add(){}, remove(){}, contains(){ return false; } },
    addEventListener(){}, setAttribute(){}, querySelector(){ return null; }, closest(){ return null; }, focus(){}, appendChild(){}, remove(){} };
  return els[id];
}
els['sqlWasmB64'] = { textContent: wasmB64, id: 'sqlWasmB64' };

const sb = { console, Date, Math, Number, String, Object, Array, JSON, isNaN, isFinite, parseFloat, parseInt, RegExp,
  Uint8Array, Int8Array, Uint32Array, Int32Array, Float64Array, ArrayBuffer, WebAssembly, TextDecoder, TextEncoder, Buffer, process,
  setTimeout:(f)=>setTimeout(f,5000), clearTimeout, setInterval:()=>0, clearInterval(){},
  atob: s => Buffer.from(s, 'base64').toString('binary'),
  confirm:()=>true, alert(){}, indexedDB:{open(){return{}}}, localStorage:{getItem:()=>null,setItem(){}},
  document:{ getElementById: el, querySelector:s=>el(s.replace(/^#/,'')), querySelectorAll:()=>[], addEventListener(){},
    createElement:()=>({style:{},dataset:{},remove(){},click(){},appendChild(){},setAttribute(){}}), head:{appendChild(){}}, body:{appendChild(){}} },
  location:{search:''}, FileReader:function(){}, Blob:function(){}, URL:{createObjectURL:()=>'',revokeObjectURL(){}}, fetch:()=>Promise.reject(new Error('no')) };
sb.window=sb; sb.self=sb; sb.globalThis=sb;
vm.createContext(sb);

const loader = html.match(/<!-- SQLJS:START[^>]*-->\s*<script>([\s\S]*?)<\/script>/);
vm.runInContext(loader[1], sb);
const main = html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/)[0].replace(/^<script>\n/,'').replace(/<\/script>$/,'');
vm.runInContext(main, sb);
const P = sb.__PANEL__;

const MODE = process.argv[2] || 'inspect';

(async () => {
  const SQL = await P._ensureSql();
  const dbPath = path.join(dir, 'holding.sqlite');
  const buf = fs.readFileSync(dbPath);
  const db = new SQL.Database(new Uint8Array(buf));
  const r = db.exec("SELECT v FROM setting WHERE k='cfg'");
  const cfg = r.length ? JSON.parse(r[0].values[0][0]) : null;
  if (MODE === 'inspect') {
    if (!cfg) { console.log('库里无 cfg'); return; }
    console.log('库内 cfg targets governance:');
    cfg.targets.forEach(t => console.log('  ', t.code, t.name, '→', t.governance || '(缺)'));
    console.log('库内 margin keys:', Object.keys(cfg.margin || {}).join(','));
    console.log('库内 rules keys:', Object.keys(cfg.rules || {}).join(','));
    const r2 = db.exec("SELECT k,v FROM setting WHERE k IN ('cfgSyncedAt','cfgSource')");
    console.log('cfgSyncedAt/cfgSource:', r2.length ? JSON.stringify(r2[0].values) : '无');
    return;
  }
  if (MODE === 'sync') {
    // 用 config.js 覆盖库内 cfg，并写 cfgSyncedAt/cfgSource
    const cfgJs = fs.readFileSync(path.join(dir, 'config.js'), 'utf8');
    const w = {}; vm.runInNewContext(cfgJs, { window: w, console });
    const newCfg = w.PANEL_CONFIG;
    const now = new Date().toISOString();
    db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfg', JSON.stringify(newCfg)]);
    db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSyncedAt', now]);
    db.run("INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)", ['cfgSource', 'sync']);
    fs.writeFileSync(dbPath, Buffer.from(db.export()));
    console.log('已写入 config.js 到 holding.sqlite');
    console.log('新库 targets governance:');
    newCfg.targets.forEach(t => console.log('  ', t.code, t.name, '→', t.governance || '(缺)'));
    console.log('cfgSyncedAt:', now, ' cfgSource: sync');
    return;
  }
})().catch(e => { console.error('ERR', e.message, e.stack); process.exit(1); });
